"use client";

import { useState } from "react";
import Link from "next/link";
import RazorpayButton from "@/components/RazorpayButton";

/**
 * /closed — shown nightly 10pm-6am IST until Dec 5, 2026 (when the free
 * Appwrite reads reset).
 *
 * Fully static: no database reads. Kept plain and text-first — a notice,
 * not a shop. Visitors can enter a temporary access code (generated by
 * the assistant) to use the site for the night, or an admin can enter
 * directly. 3 wrong codes block the IP (contact the admin to unblock).
 */
const WHATSAPP_GROUP_URL =
  "https://chat.whatsapp.com/DDE3VssePR77bBTsesoyXm";

export default function ClosedPage() {
  const [code, setCode] = useState("");
  const [codeMsg, setCodeMsg] = useState("");
  const [codeBusy, setCodeBusy] = useState(false);
  const [adminMsg, setAdminMsg] = useState("");
  const [adminBusy, setAdminBusy] = useState(false);

  const submitCode = async (e: React.FormEvent) => {
    e.preventDefault();
    setCodeMsg("");
    setCodeBusy(true);
    try {
      const res = await fetch("/api/night-access/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code }),
      });
      const data = (await res.json()) as { ok?: boolean; error?: string };
      if (res.ok && data.ok) {
        window.location.href = "/";
        return;
      }
      setCodeMsg(data.error || "Wrong access code.");
    } catch {
      setCodeMsg("Could not verify the code. Please try again.");
    } finally {
      setCodeBusy(false);
    }
  };

  const adminEnter = async () => {
    setAdminMsg("");
    setAdminBusy(true);
    try {
      const res = await fetch("/api/night-access/admin", { method: "POST" });
      const data = (await res.json()) as { ok?: boolean; error?: string };
      if (res.ok && data.ok) {
        window.location.href = "/";
        return;
      }
      setAdminMsg(data.error || "Admin access failed. Are you logged in as an admin?");
    } catch {
      setAdminMsg("Could not verify admin access. Please try again.");
    } finally {
      setAdminBusy(false);
    }
  };

  return (
    <main className="mx-auto flex min-h-screen max-w-2xl flex-col items-center justify-center px-4 py-12 text-center">
      <h1 className="text-3xl font-bold">ExamArchive is closed for the night</h1>
      <p className="mt-3 text-base leading-relaxed text-on-surface-variant">
        The site is open every day from 6am to 10pm (IST). It closes overnight
        to save server usage — our free server limit is 92% used. This nightly
        closure runs until Dec 5, 2026, when the limit resets.
      </p>

      {/* Temporary access code */}
      <form
        onSubmit={submitCode}
        className="mt-8 w-full rounded-xl border p-5 text-left"
      >
        <p className="text-sm font-bold">Have a temporary access code?</p>
        <p className="mt-1 text-sm leading-snug text-on-surface-variant">
          Enter it to use the site for the night. 3 wrong codes block this IP
          (contact the admin to unblock it).
        </p>
        <div className="mt-3 flex gap-2">
          <input
            value={code}
            onChange={(e) => setCode(e.target.value)}
            placeholder="Access code"
            autoComplete="off"
            className="min-w-0 flex-1 rounded-md border px-3 py-2 text-sm uppercase"
          />
          <button
            type="submit"
            disabled={codeBusy || code.trim().length === 0}
            className="shrink-0 rounded-md bg-primary px-4 py-2 text-sm font-bold text-white disabled:opacity-50"
          >
            {codeBusy ? "Checking..." : "Enter"}
          </button>
        </div>
        {codeMsg && (
          <p className="mt-2 text-sm font-semibold text-red-600 dark:text-red-400">
            {codeMsg}
          </p>
        )}
      </form>

      {/* Admin entry */}
      <div className="mt-4 w-full rounded-xl border p-5 text-left">
        <p className="text-sm font-bold">Admin?</p>
        <p className="mt-1 text-sm leading-snug text-on-surface-variant">
          If you are logged in as an admin, enter directly without a code.
        </p>
        <button
          type="button"
          onClick={adminEnter}
          disabled={adminBusy}
          className="mt-3 rounded-md border px-4 py-2 text-sm font-bold disabled:opacity-50"
        >
          {adminBusy ? "Checking..." : "Enter as admin"}
        </button>
        {adminMsg && (
          <p className="mt-2 text-sm font-semibold text-red-600 dark:text-red-400">
            {adminMsg}
          </p>
        )}
      </div>

      <p className="mt-6 text-base">
        Need something? Ask in the{" "}
        <a
          href={WHATSAPP_GROUP_URL}
          target="_blank"
          rel="noopener noreferrer"
          className="font-semibold text-primary underline"
        >
          WhatsApp group
        </a>
        .
      </p>

      <div className="mt-6">
        <p className="text-sm text-on-surface-variant">
          To support the site, pay securely via Razorpay:
        </p>
        <div className="mt-2 flex justify-center">
          <RazorpayButton />
        </div>
      </div>

      <Link href="/" className="mt-6 text-sm font-semibold text-primary underline">
        Back to home (reopens 6am)
      </Link>
    </main>
  );
}
